"""Reproduce source-labelled teaching schematics for Smith & Le, ICLR 2018."""
from pathlib import Path
from html import escape
import math
out=Path(__file__).resolve().parents[1]/'public/figures/bayesian-sgd'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19): return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,a,b,color='#ddd9fa',w=270):
 return f'<rect x="{x}" y="{y}" width="{w}" height="90" rx="12" fill="{color}" stroke="#71849a"/>'+text(x+12,y+32,a)+text(x+12,y+65,b,16)
def arrow(x,y,a,b): return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
 (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / Fitting labels is not enough','Conceptual comparison based on the logistic-regression experiment; no measured values.',box(30,100,'Same 800 MNIST images','400 zeros + 400 ones','#d4eee7')+arrow(310,145,345,145)+box(350,100,'Informative labels','Fit a reusable distinction')+arrow(630,145,665,145)+box(670,100,'Accurate test predictions','Confidence still matters',w=240)+box(350,270,'Randomized labels','Fit arbitrary assignments')+arrow(160,200,160,315)+arrow(160,315,340,315)+arrow(630,315,665,315)+box(670,270,'Chance test predictions','Can still fit training labels',w=240)+text(30,414,'Evidence asks how much prior probability supports a good fit, not only whether a fit exists.',18))
svg('architecture','02 / SGD trains a predictor; evidence analyzes fit','Functional architecture of the shallow MNIST experiment, with tensor dimensions.',box(30,100,'A · Batch X','B × 784 pixels','#d4eee7')+arrow(310,145,345,145)+box(350,100,'B · Dense + ReLU','B × 800 hidden activations')+arrow(630,145,665,145)+box(670,100,'C · Softmax output','B × 10 class probabilities',w=240)+box(30,270,'F · Update weights ω','Batch gradient + momentum')+box(350,270,'E · Backpropagate','Gradient for every weight')+box(670,270,'D · Cross-entropy','Probabilities + B labels','#ffe6cb',240)+arrow(790,200,790,260)+arrow(660,315,630,315)+arrow(340,315,310,315)+text(30,413,'Evidence is a separate analysis—not an extra loss used by this MNIST network.',18))
svg('representation','03 / Height versus probability mass','Toy Gaussian peaks with equal height; wider area carries more local mass.', ''.join(f'<path d="'+ ' '.join(('M' if i==0 else 'L')+f'{x:.1f} {330-210*math.exp(-((x-c)/s)**2/2):.1f}' for i,x in enumerate(range(40,490,2)))+f'" fill="none" stroke="{color}" stroke-width="4"/>' for c,s,color in [(200,18,'#8264b0'),(350,65,'#218c77')])+arrow(35,330,505,330)+text(60,370,'Parameter coordinate ω',18)+box(540,110,'Purple: narrow peak','High density in a small region')+box(540,265,'Green: broad peak','Same height; larger area','#d4eee7')+text(30,415,'Schematic e⁻ᶜ curves. Evidence also depends on the prior measure and other minima.',18))
svg('training','04 / Training and prediction follow different paths','Training loop versus frozen point prediction; exact Bayesian prediction integrates parameters.',box(30,100,'Sample a fresh batch','Data fixed; indices refreshed','#d4eee7')+arrow(310,145,345,145)+box(350,100,'A → B → C → D → E','Forward, loss, backpropagate')+arrow(630,145,665,145)+box(670,100,'F · Carry ω and velocity','Update both, repeat',w=240)+box(30,270,'At prediction: freeze ω','New image; no training label','#d4eee7')+arrow(310,315,345,315)+box(350,270,'B → C only','Class probabilities → argmax')+arrow(630,315,665,315)+box(670,270,'One point predictor','No posterior sampler here',w=240)+text(30,415,'Bayesian ideal: average probabilities over the posterior. It is a separate integral.',18))
g=0.1*(1000/100-1)
assert abs(g-.9)<1e-12
svg('numbers','05 / Trace one scalar SGD update','Computed toy for one coordinate of box F; no momentum and no trained model.',box(30,100,'A–E · Toy batch gradient','Mean = 0.3; full mean = 0.2','#d4eee7')+arrow(310,145,345,145)+box(350,100,'F · ω = 1; ε = 0.1','Δω = −0.1 × 0.3 = −0.03')+arrow(630,145,665,145)+box(670,100,'Carry ω = 0.97','Next batch gives new error',w=240)+box(30,270,'Full-gradient drift','−0.1 × 0.2 = −0.02','#d4eee7')+box(350,270,'This batch’s deviation','−0.1 × (0.3 − 0.2) = −0.01')+box(670,270,'N = 1000; B = 100','g = 0.9 (not the deviation)','#ffe6cb',240)+text(30,415,'The realized update error is −0.01; g scales covariance across possible batches.',18))
svg('iteration','06 / Constant noise does not mean identical steps','Computed no-momentum example with exact finite-batch correction.',box(30,100,'Start: N = 1000','ε = 0.1; B = 100 → g = 0.9','#d4eee7')+arrow(310,145,345,145)+box(350,100,'Double ε and B','ε = 0.2; B = 200 → g = 0.8')+arrow(630,145,665,145)+box(670,100,'Exact correction','B = 1000 / (1 + 0.9/0.2)','#ffe6cb',240)+text(680,230,'≈ 181.8; round to a batch',16)+box(30,285,'Full batch: B = N','g = 0; small-batch rule fails','#d4eee7')+box(350,285,'Small B relative to N','g ≈ εN/B gives linear scaling')+box(670,285,'Momentum m < 1','g ≈ εN / [B(1 − m)]',w=240)+text(30,430,'Scaling preserves a model of noise intensity; stability and gradient covariance still matter.',18),460)
svg('evidence','07 / A quantitative protocol, not invented curve points','Source-reported numerical settings and scaling ranges from Figures 4–7.',text(30,95,'MNIST · 784 → 800 ReLU → 10 · no L2 · default ε = 1, m = 0.9',19)+box(30,130,'Figure 4 · Batch sweep','B from 1 to 1000; 10,000 steps','#d4eee7',420)+box(490,130,'Reported outcome','B ≲ 10 fails to train; interior peak',w=420)+box(30,250,'Figure 5 · Learning-rate sweep','10,000 / ε steps; trend over 100×','#d4eee7',420)+box(490,250,'Reported outcome','Peak quality drops around ε ≳ 3',w=420)+box(30,370,'Figure 6 · Dataset-size sweep','10,000 steps; five runs per curve','#d4eee7',420)+box(490,370,'Reported outcome','Bopt ∝ N once N ≳ 20,000',w=420)+text(30,510,'Exact accuracy percentages are not tabulated here; see the linked source plots.',18),540)
print('Generated seven SVGs; scalar update and noise-scale arithmetic checked.')
